mapper.select:
SELECT tracking_response_id, tracking_process_id, request_tracking_id, receive_time, receive_val, receive_status, receive_msg, receive_payload FROM tracking_response_record WHERE 1=1
and tracking_response_id = #{trackingResponseId}
and tracking_process_id = #{trackingProcessId}
and request_tracking_id = #{requestTrackingId}
and tracking_response_id >= #{startProcId}
order by tracking_response_id desc
order by tracking_response_id
limit 0, #{limitBufferSize}

select A.* from ( SELECT tracking_response_id, tracking_process_id, request_tracking_id, receive_time, receive_val, receive_status, receive_msg, receive_payload FROM tracking_response_record WHERE 1=1
and tracking_response_id = #{trackingResponseId}
and tracking_process_id = #{trackingProcessId}
and request_tracking_id = #{requestTrackingId}
and tracking_response_id >= #{startProcId}
order by tracking_response_id asc
limit 0, #{limitBufferSize}
) A order by tracking_response_id desc limit 0, 1

  		SELECT count(*) cnt
		FROM tracking_response_record
		WHERE 1=1

			 and tracking_response_id = #{trackingResponseId}


			 and tracking_process_id = #{trackingProcessId}


			 and request_tracking_id = #{requestTrackingId}



			 and tracking_response_id >= #{startProcId}




				order by tracking_response_id desc		


				order by tracking_response_id		



			 limit 0, #{limitBufferSize}

mapper.update:
  	UPDATE tracking_response_record
	SET

			receive_time = #{receiveTime},


			receive_val = #{receiveVal},


			receive_status = #{receiveStatus},


			receive_msg = #{receiveMsg},


			receive_payload = #{receivePayload}

	WHERE 
		tracking_response_id = #{trackingResponseId}
		and tracking_process_id = #{trackingProcessId}

mapper.select:
SELECT CONCAT(
         JSON_UNQUOTE(JSON_EXTRACT(receive_msg, '$[0].measurement_date')),
         '|', receive_val)
  FROM tracking_response_record
 WHERE tracking_process_id = #{trackingProcessId}

   AND JSON_UNQUOTE(JSON_EXTRACT(receive_msg, '$[0].measurement_date')) >= #{fromObservedAt}

mapper.delete:
DELETE r FROM tracking_response_record r INNER JOIN data_event_tracking_request_info q ON q.request_tracking_id = r.request_tracking_id WHERE q.req_trck_cmd_status IN
#{item}
AND q.req_status_change_time < DATE_SUB(NOW(), INTERVAL #{retentionDays} DAY)

DELETE d FROM tracking_response_data d INNER JOIN tracking_process_info p ON p.tracking_process_identifier = d.tracking_process_identifier INNER JOIN data_event_tracking_request_info q ON q.request_tracking_id = p.request_tracking_id WHERE q.req_trck_cmd_status IN
#{item}
AND q.req_status_change_time < DATE_SUB(NOW(), INTERVAL #{retentionDays} DAY)
